const VERSION='shirogane-wiki-1.0.0';const FILES=['./','index.html','style.css','app.js','icon.svg','manifest.webmanifest','data/catalog.js','data/wiki.js',...Array.from({length:10},(_,i)=>'data/tome-'+(i+1)+'.js')];self.addEventListener('install',event=>event.waitUntil(caches.open(VERSION).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));self.addEventListener('activate',event=>event.waitUntil(Promise.all([caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==VERSION).map(k=>caches.delete(k)))),self.clients.claim()]).then(()=>self.clients.matchAll()).then(clients=>clients.forEach(c=>c.postMessage('offline-ready')))));self.addEventListener('fetch',event=>{if(event.request.method==='GET'&&new URL(event.request.url).origin===self.location.origin)event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request)));});
